#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ScaledPanel's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/scaled_panel.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The coordinate space the children's design bounds are written in; it scales to the arranged size. Throws std::invalid_argument unless both sides are finite and positive.
template <typename Declaring>
struct ScaledPanelDesignSizeCapability {
    PropertyCell<Size, ScaledPanelDesignSizeCapability<Declaring>> design_size{Size{1.0, 1.0}};

    static void assign(ScaledPanelDesignSizeCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.design_size), incoming);
        if (!capability.design_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.design_size));
    }
};

// Every ScaledPanel capability, in the order the declaring class takes them.
template <typename Declaring>
struct ScaledPanelCapabilities : public ScaledPanelDesignSizeCapability<Declaring> {};

} // namespace gui_forms
